import json
p='cfc8badb-6fae-4dfc-a72a-a821c06d1399.jsonl'
rows=[]
with open(p) as f:
    for line in f:
        line=line.strip()
        if not line: continue
        try: rows.append(json.loads(line))
        except: pass
print('total rows', len(rows))
# print last N user/assistant text messages
def txt(m):
    c=m.get('message',{}).get('content')
    if isinstance(c,str): return c
    if isinstance(c,list):
        out=[]
        for b in c:
            if b.get('type')=='text': out.append(b['text'])
            elif b.get('type')=='tool_use': out.append('[TOOL_USE %s] %s'%(b.get('name'), json.dumps(b.get('input'),ensure_ascii=False)[:300]))
            elif b.get('type')=='tool_result':
                cc=b.get('content')
                if isinstance(cc,list):
                    cc=' '.join(x.get('text','') for x in cc if isinstance(x,dict))
                out.append('[TOOL_RESULT] '+str(cc)[:300])
        return '\n'.join(out)
    return ''
for r in rows[-40:]:
    m=r.get('message') or {}
    role=m.get('role') or r.get('type')
    print('=====', role, r.get('timestamp',''))
    print(txt(r)[:1500])
EOF

